css:
.d-unsaved-navigation-guard{width:100%;max-width:430px;min-width:0;color:var(--ink);font:inherit;font-size:14px;line-height:1.5;overflow-wrap:anywhere}
.d-unsaved-navigation-guard *,.d-unsaved-navigation-guard *::before,.d-unsaved-navigation-guard *::after{box-sizing:border-box}
.d-unsaved-navigation-guard [hidden]{display:none!important}
.d-unsaved-navigation-guard .d-row{display:flex;flex-wrap:wrap;align-items:center;gap:8px;margin:8px 0}
.d-unsaved-navigation-guard .d-note{display:block;margin:8px 0 0;color:var(--muted);font-size:12px;min-height:1.5em}
.d-unsaved-navigation-guard label{display:block;margin:8px 0}
.d-unsaved-navigation-guard input,.d-unsaved-navigation-guard select,.d-unsaved-navigation-guard textarea,.d-unsaved-navigation-guard button{font:inherit;color:inherit;max-width:100%;min-width:0}
.d-unsaved-navigation-guard input:not([type=checkbox]):not([type=radio]),.d-unsaved-navigation-guard select,.d-unsaved-navigation-guard textarea{width:100%;padding:8px;border:1px solid var(--line);border-radius:var(--radius-control);background:var(--paper)}
.d-unsaved-navigation-guard button{padding:6px 10px;border:1px solid var(--line);border-radius:var(--radius-control);background:var(--paper);cursor:pointer}
.d-unsaved-navigation-guard button:disabled{opacity:.5;cursor:default}
.d-unsaved-navigation-guard :focus-visible{outline:2px solid var(--ink);outline-offset:3px}
.d-unsaved-navigation-guard [aria-invalid=true]{border-color:var(--warn)!important}
.d-unsaved-navigation-guard .d-scroll{max-width:100%;overflow:auto}
.d-unsaved-navigation-guard table{width:100%;border-collapse:collapse;font-size:12px;text-align:left}
.d-unsaved-navigation-guard th,.d-unsaved-navigation-guard td{padding:7px;border-bottom:1px solid var(--line);vertical-align:top}
.d-unsaved-navigation-guard caption{text-align:left;font-weight:600;margin-bottom:8px}
.d-unsaved-navigation-guard progress{width:100%;accent-color:var(--ink)}
.d-unsaved-navigation-guard pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px}
.d-unsaved-navigation-guard h3,.d-unsaved-navigation-guard p{margin:8px 0}
.d-unsaved-navigation-guard [aria-pressed=true],.d-unsaved-navigation-guard [aria-selected=true]{border-color:var(--ink);font-weight:650}
.d-unsaved-navigation-guard .d-grow{flex:1;min-width:100px}
.d-unsaved-navigation-guard summary{cursor:pointer;padding:6px 0}
.d-unsaved-navigation-guard ul,.d-unsaved-navigation-guard ol{padding-left:24px}
.d-unsaved-navigation-guard dialog{max-width:min(360px,90vw);background:var(--paper);color:var(--ink);border:1px solid var(--line);border-radius:var(--radius-control);padding:16px}.d-unsaved-navigation-guard dialog::backdrop{background:#0005}

init:
root => {
 const q = selector => root.querySelector(selector);
 const qa = selector => [...root.querySelectorAll(selector)];
 const say = text => { const out = q('[data-out]'); if (out) out.textContent = text; };
 ((root,q,qa,say)=>{const draft=q('[data-draft]'),dialog=q('[data-dialog]');let saved=draft.value;const leave=()=>say('已切到素材视图（演示）');q('[data-save]').onclick=()=>{saved=draft.value;say('当前草稿已存入本次演示');};q('[data-leave]').onclick=()=>{if(draft.value===saved)leave();else dialog.showModal();};q('[data-stay]').onclick=()=>{dialog.close();draft.focus();};q('[data-discard]').onclick=()=>{draft.value=saved;dialog.close();leave();};})(root, q, qa, say);
}
